// Vennaert Sales Werkplek — client-side demo. Data: ../data/*.json (generated by etl/pipeline.py).
import { createTour } from "../assets/tour.js";

const $ = (s) => document.querySelector(s);
const NL = "nl-BE";
const eur0 = (v) => new Intl.NumberFormat(NL, { style: "currency", currency: "EUR", maximumFractionDigits: 0 }).format(v);
const eur2 = (v) => new Intl.NumberFormat(NL, { style: "currency", currency: "EUR", minimumFractionDigits: 2 }).format(v);
const int = (v) => new Intl.NumberFormat(NL).format(v);
const pct = (v) => `${new Intl.NumberFormat(NL, { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(v)} %`;
const compact = (v) => (Math.abs(v) >= 1e6 ? `${(v / 1e6).toLocaleString(NL, { maximumFractionDigits: 1 })} mln` : Math.abs(v) >= 1e3 ? `${Math.round(v / 1e3)}k` : `${Math.round(v)}`);
const MONTHS = ["jan", "feb", "mrt", "apr", "mei", "jun", "jul", "aug", "sep", "okt", "nov", "dec"];
const PERIODS = { ytd: ["2026-01", "2026-09"], q3: ["2026-07", "2026-09"], "12m": ["2025-10", "2026-09"], 2025: ["2025-01", "2025-12"] };
const SVGNS = "http://www.w3.org/2000/svg";

let D, Q, R;
const state = { period: "ytd", segment: "*", qIndex: 0, qFilter: "all" };

// ------------------------------------------------------------------ small DOM helpers
function el(tag, attrs = {}, text) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  if (text !== undefined) node.textContent = text;
  return node;
}
function svg(tag, attrs = {}) {
  const node = document.createElementNS(SVGNS, tag);
  for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
  return node;
}
function table(target, head, rows, numCols = []) {
  const t = el("table");
  const tr = el("tr");
  head.forEach((h, i) => tr.append(el("th", numCols.includes(i) ? { class: "num" } : {}, h)));
  const thead = el("thead");
  thead.append(tr);
  t.append(thead);
  const tb = el("tbody");
  rows.forEach((r) => {
    const row = el("tr");
    r.forEach((c, i) => row.append(el("td", numCols.includes(i) ? { class: "num" } : {}, c)));
    tb.append(row);
  });
  t.append(tb);
  target.replaceChildren(t);
}
function tile(label, value, sub, subClass = "") {
  const t = el("div", { class: "tile" });
  t.append(el("div", { class: "label" }, label), el("div", { class: "value" }, value));
  if (sub) t.append(el("div", { class: `sub ${subClass}` }, sub));
  return t;
}

// ------------------------------------------------------------------ tooltip
const tip = $("#tooltip");
function showTip(evt, title, rows) {
  tip.replaceChildren(el("strong", {}, title));
  rows.forEach(([color, label, value]) => {
    const r = el("div", { class: "row" });
    if (color) r.append(el("span", { class: "k", style: `background:${color}` }));
    r.append(el("span", {}, label), el("b", {}, value));
    tip.append(r);
  });
  tip.classList.remove("hidden");
  const x = Math.min(evt.clientX + 14, window.innerWidth - tip.offsetWidth - 8);
  const y = Math.min(evt.clientY + 14, window.innerHeight - tip.offsetHeight - 8);
  tip.style.left = `${x}px`;
  tip.style.top = `${y}px`;
}
const hideTip = () => tip.classList.add("hidden");

// ------------------------------------------------------------------ charts (inline SVG)
// clean axis: a round step (1/2/2.5/5 × 10^k) for about four intervals, max rounded up to a whole step
function niceScale(v, intervals = 4) {
  const raw = (v || 1) / intervals, p = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * p).find((m) => m >= raw);
  const n = Math.ceil(v / step);
  return { max: n * step, step, n };
}
const niceMax = (v) => niceScale(v).max;

// columns (one bar series) + line series on one axis, crosshair tooltip per month
const widthOf = (target, fallback = 760) => Math.max(300, Math.round(target.clientWidth) || fallback);

function monthChart(target, labels, bar, lines) {
  const W = widthOf(target), H = W < 520 ? 240 : 300, m = { l: 48, r: 12, t: 12, b: 28 };
  const all = [...bar.values, ...lines.flatMap((s) => s.values)].filter((v) => v != null);
  const { max, step, n } = niceScale(Math.max(...all));
  const iw = W - m.l - m.r, ih = H - m.t - m.b, band = iw / labels.length;
  const y = (v) => m.t + ih - (v / max) * ih;
  const s = svg("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": `${bar.name} per maand` });
  for (let i = 0; i <= n; i++) {
    const v = step * i;
    s.append(svg("line", { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v), stroke: i ? "var(--viz-grid)" : "var(--viz-axis)" }));
    const t = svg("text", { x: m.l - 6, y: y(v) + 4, "text-anchor": "end" });
    t.textContent = compact(v);
    s.append(t);
  }
  const bw = Math.min(24, band * 0.55);
  labels.forEach((lab, i) => {
    const cx = m.l + band * i + band / 2;
    const v = bar.values[i];
    if (v != null && v > 0) {
      const h = ih - (y(v) - m.t), r = Math.min(4, h / 2);
      s.append(svg("path", { d: `M${cx - bw / 2},${m.t + ih} V${y(v) + r} q0,-${r} ${r},-${r} H${cx + bw / 2 - r} q${r},0 ${r},${r} V${m.t + ih} Z`, fill: bar.color }));
    }
    const t = svg("text", { x: cx, y: H - 8, "text-anchor": "middle" });
    t.textContent = lab;
    s.append(t);
  });
  lines.forEach((ln) => {
    const pts = ln.values.map((v, i) => (v == null ? null : [m.l + band * i + band / 2, y(v)]));
    let d = "";
    pts.forEach((p, i) => { if (p) d += `${d && pts[i - 1] ? "L" : "M"}${p[0]},${p[1]} `; });
    s.append(svg("path", { d, fill: "none", stroke: ln.color, "stroke-width": 2, "stroke-linejoin": "round", "stroke-linecap": "round" }));
    pts.forEach((p) => p && s.append(svg("circle", { cx: p[0], cy: p[1], r: 4, fill: ln.color, stroke: "var(--viz-surface)", "stroke-width": 2 })));
  });
  const cross = svg("line", { y1: m.t, y2: m.t + ih, stroke: "var(--viz-axis)", visibility: "hidden" });
  s.append(cross);
  labels.forEach((lab, i) => {
    const hit = svg("rect", { x: m.l + band * i, y: m.t, width: band, height: ih, fill: "transparent", tabindex: 0 });
    const show = (evt) => {
      const cx = m.l + band * i + band / 2;
      cross.setAttribute("x1", cx); cross.setAttribute("x2", cx); cross.setAttribute("visibility", "visible");
      const rows = [[bar.color, bar.name, bar.values[i] == null ? "—" : eur0(bar.values[i])], ...lines.map((l) => [l.color, l.name, l.values[i] == null ? "—" : eur0(l.values[i])])];
      const r = hit.getBoundingClientRect();
      showTip(evt.clientX ? evt : { clientX: r.left + r.width / 2, clientY: r.top + 20 }, lab, rows);
    };
    hit.addEventListener("pointermove", show);
    hit.addEventListener("focus", show);
    hit.addEventListener("pointerleave", () => { hideTip(); cross.setAttribute("visibility", "hidden"); });
    hit.addEventListener("blur", hideTip);
    s.append(hit);
  });
  target.replaceChildren(s);
}

// horizontal bars; optional second bar (inner) and optional target tick
function hbars(target, rows, { color = "var(--s1)", color2 = "var(--s3)", name = "Waarde", name2, targetName = "Target", fmt = eur0 } = {}) {
  const W = widthOf(target), rowH = 30, m = { l: W < 520 ? 118 : 150, r: 92, t: 6, b: 6 };
  const H = m.t + m.b + rows.length * rowH;
  const max = niceMax(Math.max(...rows.map((r) => Math.max(r.value, r.target || 0, r.value2 || 0))));
  const iw = W - m.l - m.r, x = (v) => m.l + (v / max) * iw;
  const s = svg("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": name });
  s.append(svg("line", { x1: m.l, x2: m.l, y1: m.t, y2: H - m.b, stroke: "var(--viz-axis)" }));
  rows.forEach((r, i) => {
    const cy = m.t + i * rowH + rowH / 2, bh = r.value2 != null ? 10 : 16;
    const lab = svg("text", { x: m.l - 8, y: cy + 4, "text-anchor": "end" });
    const maxLen = W < 520 ? 16 : 22;
    lab.textContent = r.label.length > maxLen ? `${r.label.slice(0, maxLen - 1)}…` : r.label;
    s.append(lab);
    const bar = (v, yy, h, c) => {
      const w = Math.max(0, x(v) - m.l), rr = Math.min(4, w / 2, h / 2);
      if (w > 0) s.append(svg("path", { d: `M${m.l},${yy} H${m.l + w - rr} q${rr},0 ${rr},${rr} V${yy + h - rr} q0,${rr} -${rr},${rr} H${m.l} Z`, fill: c }));
    };
    if (r.value2 != null) { bar(r.value, cy - bh - 1, bh, color); bar(r.value2, cy + 1, bh, color2); }
    else bar(r.value, cy - bh / 2, bh, color);
    if (r.target) s.append(svg("line", { x1: x(r.target), x2: x(r.target), y1: cy - 11, y2: cy + 11, stroke: "var(--text)", "stroke-width": 2 }));
    const val = svg("text", { x: Math.max(x(r.value), r.target ? x(r.target) : 0) + 6, y: cy + 4, class: "lbl" });
    val.textContent = r.note ?? fmt(r.value);
    s.append(val);
    const hit = svg("rect", { x: 0, y: cy - rowH / 2, width: W, height: rowH, fill: "transparent", tabindex: 0 });
    const show = (evt) => {
      const rowsT = [[color, name, fmt(r.value)]];
      if (r.value2 != null) rowsT.push([color2, name2, fmt(r.value2)]);
      if (r.target) rowsT.push(["var(--text)", targetName, fmt(r.target)], [null, "Realisatie", pct((100 * r.value) / r.target)]);
      const b = hit.getBoundingClientRect();
      showTip(evt.clientX ? evt : { clientX: b.left + 160, clientY: b.top }, r.label, rowsT);
    };
    hit.addEventListener("pointermove", show);
    hit.addEventListener("focus", show);
    hit.addEventListener("pointerleave", hideTip);
    hit.addEventListener("blur", hideTip);
    s.append(hit);
  });
  target.replaceChildren(s);
}

// waterfall: first and totals as full bars, steps as floating bars
function waterfall(target, steps) {
  const W = widthOf(target), H = 320, m = { l: 56, r: 12, t: 22, b: 64 };
  const { max, step, n } = niceScale(Math.max(...steps.map((s) => s.value)));
  const lo = 0; // bars measure magnitude: the axis starts at zero, the table below carries the exact steps
  const iw = W - m.l - m.r, ih = H - m.t - m.b, band = iw / steps.length;
  const y = (v) => m.t + ih - ((v - lo) / (max - lo)) * ih;
  const s = svg("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": "Brug van Excel-rapport naar finance" });
  for (let i = 0; i <= n; i++) {
    const v = step * i;
    s.append(svg("line", { x1: m.l, x2: W - m.r, y1: y(v), y2: y(v), stroke: i ? "var(--viz-grid)" : "var(--viz-axis)" }));
    const t = svg("text", { x: m.l - 6, y: y(v) + 4, "text-anchor": "end" });
    t.textContent = compact(v);
    s.append(t);
  }
  const bw = Math.min(48, band * 0.6);
  steps.forEach((st, i) => {
    const cx = m.l + band * i + band / 2;
    const top = st.total ? st.value : st.start, bottom = st.total ? lo : st.start + st.value;
    const y1 = y(Math.max(top, bottom)), y2 = y(Math.min(top, bottom));
    s.append(svg("rect", { x: cx - bw / 2, y: y1, width: bw, height: Math.max(2, y2 - y1), rx: 3, fill: st.total ? "var(--s1)" : "var(--s8)" }));
    const v = svg("text", { x: cx, y: y1 - 6, "text-anchor": "middle", class: "lbl" });
    v.textContent = st.total ? compact(st.value) : `−${compact(-st.value)}`;
    s.append(v);
    st.short.split("\n").forEach((line, k) => {
      const t = svg("text", { x: cx, y: H - m.b + 18 + k * 14, "text-anchor": "middle", style: W < 520 ? "font-size:10px" : "" });
      t.textContent = line;
      s.append(t);
    });
    const hit = svg("rect", { x: cx - band / 2, y: m.t, width: band, height: ih, fill: "transparent", tabindex: 0 });
    const show = (evt) => {
      const b = hit.getBoundingClientRect();
      showTip(evt.clientX ? evt : { clientX: b.left, clientY: b.top + 40 }, st.label, [[st.total ? "var(--s1)" : "var(--s8)", "Bedrag", eur2(st.value)], ...(st.lines ? [[null, "Rijen", int(st.lines)]] : [])]);
    };
    hit.addEventListener("pointermove", show);
    hit.addEventListener("focus", show);
    hit.addEventListener("pointerleave", hideTip);
    hit.addEventListener("blur", hideTip);
    s.append(hit);
  });
  target.replaceChildren(s);
}

// ------------------------------------------------------------------ data helpers
const inPeriod = (ym, p) => ym >= PERIODS[p][0] && ym <= PERIODS[p][1];
const shiftYear = (ym, d) => `${+ym.slice(0, 4) + d}${ym.slice(4)}`;
function sumCube(pred) {
  let net = 0, gm = 0, inv = 0;
  for (const [ym, rep, cat, seg, n, g, i] of D.cube) if (pred(ym, rep, cat, seg)) { net += n; gm += g; inv += i; }
  return { net, gm, inv };
}
const segOk = (seg) => state.segment === "*" || seg === state.segment;

// ------------------------------------------------------------------ views
function renderOverview() {
  const p = state.period;
  const cur = sumCube((ym, r, c, seg) => inPeriod(ym, p) && segOk(seg));
  const prev = sumCube((ym, r, c, seg) => inPeriod(shiftYear(ym, 1), p) && segOk(seg));
  const tgt = D.targets.filter(([, ym]) => inPeriod(ym, p)).reduce((a, [, , v]) => a + v, 0);
  const growth = prev.net ? (100 * (cur.net - prev.net)) / prev.net : null;
  const custKey = { ytd: "ytd", q3: "q3", "12m": "12m", 2025: "2025" }[p];
  const tiles = $("#ov-tiles");
  tiles.replaceChildren(
    tile("Netto-omzet", eur0(cur.net), growth == null ? "geen vergelijking" : `${growth >= 0 ? "▲" : "▼"} ${pct(Math.abs(growth))} vs vorig jaar`, growth >= 0 ? "delta-up" : "delta-down"),
    tile("Marge", pct((100 * cur.gm) / cur.net), eur0(cur.gm)),
    tile("Target-realisatie", state.segment === "*" && tgt ? pct((100 * cur.net) / tgt) : "—", state.segment === "*" && tgt ? `target ${eur0(tgt)}` : "targets bestaan per verkoper, niet per segment"),
    tile("Actieve klanten", int(D.customers[custKey][state.segment] || 0), "≥ 1 factuur in de periode"),
    tile("CRM-gezondheid", pct(D.kpi.dq_health_after), `was ${pct(D.kpi.dq_health_before)} vóór de opkuis`),
  );
  const months26 = MONTHS.map((_, i) => `2026-${String(i + 1).padStart(2, "0")}`);
  const val = (ym) => (ym > D.asOf.slice(0, 7) ? null : sumCube((y, r, c, seg) => y === ym && segOk(seg)).net);
  const bar = { name: "Netto-omzet 2026", color: "var(--s1)", values: months26.map(val) };
  const lines = [{ name: "2025", color: "var(--s-prev)", values: months26.map((ym) => val(shiftYear(ym, -1))) }];
  if (state.segment === "*") lines.unshift({ name: "Target 2026", color: "var(--s2)", values: months26.map((ym) => D.targets.filter(([, y]) => y === ym).reduce((a, [, , v]) => a + v, 0) || null) });
  const legend = $("#ov-legend");
  legend.replaceChildren();
  [[bar.color, bar.name, false], ...lines.map((l) => [l.color, l.name, true])].forEach(([c, n, isLine]) => {
    const li = el("li");
    li.append(el("span", { class: `key${isLine ? " line" : ""}`, style: `background:${c}` }), document.createTextNode(n));
    legend.append(li);
  });
  monthChart($("#ov-chart"), MONTHS, bar, lines);
  table($("#ov-table"), ["Maand", bar.name, ...lines.map((l) => l.name)],
    MONTHS.map((mn, i) => [mn, bar.values[i] == null ? "—" : eur0(bar.values[i]), ...lines.map((l) => (l.values[i] == null ? "—" : eur0(l.values[i])))]), [1, 2, 3]);
}

function renderSales() {
  const p = state.period;
  const byRep = new Map();
  for (const [ym, rep, cat, seg, n] of D.cube) if (inPeriod(ym, p) && segOk(seg)) byRep.set(rep, (byRep.get(rep) || 0) + n);
  const tByRep = new Map();
  for (const [rep, ym, v] of D.targets) if (inPeriod(ym, p)) tByRep.set(rep, (tByRep.get(rep) || 0) + v);
  const repName = Object.fromEntries(D.reps.map((r) => [r.code, `${r.name} (${r.code})${r.active ? "" : " — vertrokken"}`]));
  const rows = [...byRep.entries()].sort((a, b) => b[1] - a[1]).map(([rep, v]) => ({ label: repName[rep] || rep, value: v, target: state.segment === "*" ? tByRep.get(rep) : undefined }));
  hbars($("#sales-rep-chart"), rows, { name: "Netto-omzet" });
  table($("#sales-rep-table"), ["Verkoper", "Netto-omzet", "Target", "Realisatie"],
    rows.map((r) => [r.label, eur0(r.value), r.target ? eur0(r.target) : "—", r.target ? pct((100 * r.value) / r.target) : "—"]), [1, 2, 3]);

  const byCat = new Map();
  for (const [ym, rep, cat, seg, n, g] of D.cube) if (inPeriod(ym, p) && segOk(seg)) { const c = byCat.get(cat) || [0, 0]; byCat.set(cat, [c[0] + n, c[1] + g]); }
  const cats = [...byCat.entries()].sort((a, b) => b[1][0] - a[1][0]);
  hbars($("#sales-cat-chart"), cats.map(([c, [n]]) => ({ label: c, value: n })), { name: "Netto-omzet" });
  table($("#sales-cat-table"), ["Categorie", "Netto-omzet", "Marge"], cats.map(([c, [n, g]]) => [c, eur0(n), pct((100 * g) / n)]), [1, 2]);
  table($("#sales-top"), ["Klant", "Segment", "Netto-omzet", "Marge"], D.top.map(([no, name, seg, terr, rev, mg]) => [name, seg, eur0(rev), pct(mg)]), [2, 3]);
}

function renderPipeline() {
  const k = D.kpi;
  $("#pipe-tiles").replaceChildren(
    tile("Open pipeline", eur0(k.open_pipeline), `${int(k.open_opportunities)} open opportunities`),
    tile("Gewogen pipeline", eur0(k.weighted_pipeline), "bedrag × slaagkans per fase"),
    tile("Win rate (12 m)", pct(k.win_rate_12m_pct), `${int(k.won_12m)} gewonnen · ${int(k.lost_12m)} verloren`),
    tile("Vergeten deals", int(k.stale_opportunities), "> 60 dagen geen update", "delta-down"),
    tile("Zonder bedrag", int(k.open_without_amount), "offerte/onderhandeling (OPP-03)", "delta-down"),
  );
  const rows = D.pipeline.map(([stage, n, amount, weighted]) => ({ label: `${stage} (${n})`, value: amount, value2: weighted }));
  hbars($("#pipe-stage-chart"), rows, { name: "Open bedrag", name2: "Gewogen" });
  table($("#pipe-stage-table"), ["Fase", "Aantal", "Open bedrag", "Gewogen", "Zonder update > 60 d", "Zonder bedrag"],
    D.pipeline.map(([s, n, a, w, st, wo]) => [s, int(n), eur0(a), eur0(w), int(st), int(wo)]), [1, 2, 3, 4, 5]);
  table($("#pipe-stale"), ["Opportunity", "Account", "Verkoper", "Fase", "Bedrag", "Dagen stil"],
    D.stale.map(([id, acc, rep, stage, amt, days]) => [id, acc, rep, stage, amt == null ? "geen bedrag" : eur0(amt), int(days)]), [4, 5]);
}

// CRM: rules table + interactive duplicate queue
const STORAGE_SLOT = ["vennaert", "dup", "decisions", "v1"].join("-");
function loadMine() { try { return JSON.parse(localStorage.getItem(STORAGE_SLOT)) || {}; } catch { return {}; } }
function saveMine(m) { try { localStorage.setItem(STORAGE_SLOT, JSON.stringify(m)); } catch { /* private mode: keep in memory */ } }
let mine = {};

function renderCrm() {
  const h = Q.health;
  $("#crm-tiles").replaceChildren(
    tile("CRM-gezondheid vóór", pct(h.before[2]), `${int(h.before[1])} van ${int(h.before[0])} klantaccounts zonder blokkerend probleem`),
    tile("Na correcties", pct(h.after[2]), `${int(h.after[1])} van ${int(h.after[0])}`, "delta-up"),
    tile("Samengevoegd", int(D.kpi.changes_merge), "records, met auditlog"),
    tile("ERP-koppelingen", int(D.kpi.changes_link), "btw uniek + naam ≥ 80 %"),
    tile("Eigenaar overgezet", int(D.kpi.changes_reassign), "van vertrokken verkoper"),
  );
  table($("#crm-rules"), ["ID", "Regel", "Ernst", "Eigenaar", "Vóór", "Na"],
    Q.rules.map((r) => [r.id, r.title, r.severity === "blocking" ? "blokkerend" : "waarschuwing", r.owner, int(r.before), int(r.after)]), [4, 5]);
  renderQueue();
}

function queueItems() {
  return Q.pairs.filter((p) => state.qFilter === "all" || (state.qFilter === "nodup" ? p.decision === "geen duplicaat" : p.band === state.qFilter));
}
const FIELDS = [["account_id", "Account"], ["account_name", "Naam"], ["vat_raw", "Btw"], ["erp_customer_no", "ERP-klant"], ["owner_rep", "Eigenaar"], ["postcode", "Postcode"], ["city", "Gemeente"], ["email", "E-mail"], ["phone", "Telefoon"], ["created_at", "Aangemaakt"]];
function renderQueue() {
  const items = queueItems();
  if (!items.length) return;
  state.qIndex = Math.max(0, Math.min(state.qIndex, items.length - 1));
  const p = items[state.qIndex];
  const key = `${p.a[0]}|${p.b[0]}`;
  $("#q-pos").textContent = `Paar ${state.qIndex + 1} van ${items.length}`;
  const pill = $("#q-score");
  pill.textContent = `Score ${p.score} · ${p.band}`;
  pill.style.color = p.band === "waarschijnlijk" ? "var(--ok)" : "var(--warn)";
  const box = $("#q-pair");
  box.replaceChildren();
  [p.a, p.b].forEach((rec, side) => {
    const col = el("div");
    col.append(el("strong", {}, side === 0 ? "Record A (zou overleven)" : `Record B · ${p.oppB} opportunit${p.oppB === 1 ? "y" : "ies"}`));
    const dl = el("dl");
    FIELDS.forEach(([, label], i) => {
      const other = (side === 0 ? p.b : p.a)[i];
      dl.append(el("dt", {}, label), el("dd", i > 0 && (rec[i] || "") !== (other || "") ? { class: "diff" } : {}, rec[i] || "—"));
    });
    col.append(dl);
    box.append(col);
  });
  $("#q-evidence").textContent = `Bewijs: ${p.evidence}`;
  document.querySelectorAll("[data-decide]").forEach((b) => b.setAttribute("aria-pressed", String(mine[key] === b.dataset.decide)));
  const verdict = $("#q-verdict");
  if (mine[key]) {
    verdict.classList.remove("hidden");
    const same = mine[key] === p.decision;
    verdict.textContent = `${same ? "✔ Zelfde beslissing" : "✖ Andere beslissing"} als de reviewers in de case: "${p.decision}" — ${p.note}.`;
  } else verdict.classList.add("hidden");
  const decided = Object.keys(mine).length;
  const agree = Q.pairs.filter((x) => mine[`${x.a[0]}|${x.b[0]}`] === x.decision).length;
  $("#q-score-mine").textContent = decided ? `Jij besliste ${decided} ${decided === 1 ? "paar" : "paren"}; ${agree} keer hetzelfde als de reviewers. Opgeslagen in je browser.` : "";
}

function renderRecon() {
  const b = Object.fromEntries(R.bridge.map(([step, label, amount, lines]) => [step, { label, amount, lines }]));
  const s1 = b[1].amount, s2 = s1 + b[2].amount, s3 = s2 + b[3].amount;
  waterfall($("#recon-chart"), [
    { label: b[1].label, short: "Excel-\nrapport", value: s1, total: true, lines: b[1].lines },
    { label: b[2].label, short: "Dubbele\ndag", start: s1, value: b[2].amount, lines: b[2].lines },
    { label: b[3].label, short: "Credit-\nnota's ×2", start: s2, value: b[3].amount, lines: b[3].lines },
    { label: b[4].label, short: "Personeels-\nshop", start: s3, value: b[4].amount, lines: b[4].lines },
    { label: b[6].label, short: "Finance\n(GL 700000)", value: b[6].amount, total: true },
    { label: b[7].label, short: "Data-\nwarehouse", value: b[7].amount, total: true },
  ]);
  const causes = [[b[3].label, -b[3].amount, b[3].lines], [b[2].label, -b[2].amount, b[2].lines], [b[4].label, -b[4].amount, b[4].lines]];
  hbars($("#recon-causes"), causes.map(([l, v, n]) => ({ label: l.replace(" eraf", "").replace(": opgeteld i.p.v. afgetrokken (2×)", " (2×)"), value: v, note: `${eur0(v)} · ${int(n)} rijen` })), { name: "Te veel in het Excel-rapport", color: "var(--s8)" });
  table($("#recon-table"), ["Stap", "Omschrijving", "Bedrag", "Rijen"], R.bridge.map(([s, l, a, n]) => [String(s), l, eur2(a), n == null ? "" : int(n)]), [2, 3]);
  table($("#recon-monthly"), ["Maand", "Finance", "Datawarehouse", "Verschil"], R.monthly.map(([m, f, d]) => [m, eur2(f), eur2(d), eur2(Math.round((d - f) * 100) / 100)]), [1, 2, 3]);
}

// SQL console (sql.js, loaded on first use)
const PRESETS = [
  ["KPI's dit jaar", "SELECT * FROM v_kpi_ytd;"],
  ["Omzet per maand", "SELECT year_month, net_revenue, margin_pct, active_customers\nFROM v_sales_monthly\nORDER BY year_month;"],
  ["Verkoper vs target (sep)", "SELECT rep_code, rep_name, net_revenue, target_amount, attainment_pct\nFROM v_rep_month_vs_target\nWHERE year_month = '2026-09'\nORDER BY attainment_pct DESC;"],
  ["Regels vóór/na", "SELECT rule_id, title, severity, issues_before, issues_after\nFROM v_dq_rule_summary\nORDER BY rule_id;"],
  ["Duplicaatparen", "SELECT p.score, p.band, a.account_name AS a, b.account_name AS b, p.evidence\nFROM dq_duplicate_pair p\nJOIN stg_crm_accounts a ON a.account_id = p.account_a\nJOIN stg_crm_accounts b ON b.account_id = p.account_b\nWHERE p.snapshot = 'before'\nORDER BY p.score DESC\nLIMIT 25;"],
  ["Wijzigingslog", "SELECT change_type, count(*) AS n\nFROM crm_change_log\nGROUP BY change_type;"],
  ["Omzet zonder verkoper", "-- lijnen zonder verkoper kregen de eigenaar op factuurdatum (ADR-002)\nSELECT r.rep_code, count(*) AS lines, round(sum(f.net_amount), 2) AS revenue\nFROM fact_sales f JOIN dim_rep r USING (rep_key)\nWHERE f.rep_derived = 1\nGROUP BY r.rep_code ORDER BY revenue DESC;"],
];
let db = null, dbLoading = null;
function loadScript(src) {
  return new Promise((res, rej) => { const s = el("script", { src }); s.onload = res; s.onerror = rej; document.head.append(s); });
}
async function ensureDb() {
  if (db) return db;
  if (!dbLoading) {
    dbLoading = (async () => {
      $("#sql-status").textContent = "sql.js en database laden…";
      await loadScript("https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/sql-wasm.js");
      const SQL = await window.initSqlJs({ locateFile: (f) => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/${f}` });
      const buf = await (await fetch("../data/warehouse.sqlite")).arrayBuffer();
      db = new SQL.Database(new Uint8Array(buf));
      const n = db.exec("SELECT count(*) FROM sqlite_master WHERE type IN ('table','view')")[0].values[0][0];
      $("#sql-status").textContent = `Klaar: ${n} tabellen en views.`;
      return db;
    })().catch((e) => { $("#sql-status").textContent = `Laden mislukt: ${e.message}`; dbLoading = null; throw e; });
  }
  return dbLoading;
}
async function runSql() {
  const out = $("#sql-out");
  try {
    await ensureDb();
    const text = $("#sql-text").value;
    if (/\b(insert|update|delete|drop|alter|create|attach|pragma)\b/i.test(text.replace(/--.*$/gm, ""))) throw new Error("Alleen SELECT-query's in deze demo.");
    const t0 = performance.now();
    const res = db.exec(text);
    const ms = Math.round(performance.now() - t0);
    if (!res.length) { out.replaceChildren(el("p", { class: "note" }, "Geen rijen.")); return; }
    const { columns, values } = res[res.length - 1];
    const shown = values.slice(0, 200);
    const fmt = (v) => (v == null ? "NULL" : typeof v === "number" && !Number.isInteger(v) ? v.toLocaleString(NL, { maximumFractionDigits: 2 }) : String(v));
    table(out, columns, shown.map((r) => r.map(fmt)), columns.map((_, i) => i).filter((i) => typeof shown[0]?.[i] === "number"));
    $("#sql-status").textContent = `${int(values.length)} rij(en) in ${ms} ms${values.length > 200 ? " — eerste 200 getoond" : ""}.`;
  } catch (e) {
    out.replaceChildren(el("p", { class: "note" }, `Fout: ${e.message}`));
  }
}

// ------------------------------------------------------------------ tabs & wiring
const TABS = ["overview", "sales", "pipeline", "crm", "recon", "sql", "support"];
function selectTab(name) {
  currentTab = name;
  TABS.forEach((t) => {
    $(`#tab-${t}`).setAttribute("aria-selected", String(t === name));
    $(`#p-${t}`).classList.toggle("hidden", t !== name);
  });
  $("#filters").classList.toggle("hidden", !["overview", "sales"].includes(name));
  (RENDER[name] || (() => {}))();
  if (name === "sql") ensureDb().then(() => !$("#sql-out").childElementCount && runSql()).catch(() => {});
  hideTip();
}
function renderAll() { renderOverview(); renderSales(); }
let currentTab = "overview";
const RENDER = { overview: () => renderOverview(), sales: () => renderSales(), pipeline: () => renderPipeline(), recon: () => renderRecon() };

async function main() {
  [D, Q, R] = await Promise.all(["dashboard", "dq", "recon"].map((f) => fetch(`../data/${f}.json`).then((r) => r.json())));
  mine = loadMine();
  $("#asof").textContent = `Gegevens tot en met ${new Date(D.asOf).toLocaleDateString(NL, { day: "numeric", month: "long", year: "numeric" })}`;
  const segs = [...new Set(D.cube.map((r) => r[3]))].sort();
  segs.forEach((s) => $("#f-segment").append(el("option", { value: s }, s)));
  $("#f-period").addEventListener("change", (e) => { state.period = e.target.value; renderAll(); });
  $("#f-segment").addEventListener("change", (e) => { state.segment = e.target.value; renderAll(); });
  TABS.forEach((t) => $(`#tab-${t}`).addEventListener("click", () => selectTab(t)));
  $("#q-prev").addEventListener("click", () => { state.qIndex--; renderQueue(); });
  $("#q-next").addEventListener("click", () => { state.qIndex++; renderQueue(); });
  $("#q-filter").addEventListener("change", (e) => { state.qFilter = e.target.value; state.qIndex = 0; renderQueue(); });
  document.querySelectorAll("[data-decide]").forEach((b) => b.addEventListener("click", () => {
    const p = queueItems()[state.qIndex];
    mine[`${p.a[0]}|${p.b[0]}`] = b.dataset.decide;
    saveMine(mine);
    renderQueue();
  }));
  $("#q-reset").addEventListener("click", () => { mine = {}; saveMine(mine); renderQueue(); });
  PRESETS.forEach(([label, sql]) => {
    const b = el("button", { class: "btn-sm", type: "button" }, label);
    b.addEventListener("click", () => { $("#sql-text").value = sql; runSql(); });
    $("#sql-presets").append(b);
  });
  $("#sql-text").value = PRESETS[0][1];
  $("#sql-run").addEventListener("click", runSql);
  $("#sql-text").addEventListener("keydown", (e) => { if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) runSql(); });

  renderAll(); renderPipeline(); renderCrm(); renderRecon();
  let resizeTimer;
  window.addEventListener("resize", () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(() => (RENDER[currentTab] || (() => {}))(), 150); });

  const k = D.kpi;
  const multiSite = () => { state.qFilter = "nodup"; $("#q-filter").value = "nodup"; state.qIndex = 0; renderQueue(); };
  const tour = createTour([
    { text: `Een groothandel met twee waarheden: het wekelijkse Excel-rapport van sales en de omzet van finance. Dit overzicht gebruikt één definitie — die van finance — voor elk cijfer.`, focus: "#ov-tiles", before: () => selectTab("overview") },
    { text: `Q3 2026: het Excel-rapport zat ${eur2(k.recon_gap)} te hoog. Drie oorzaken, elk berekend uit de data: creditnota's opgeteld in plaats van afgetrokken, een dag twee keer geëxporteerd, en de personeelsshop. Onverklaard: ${eur2(k.recon_unexplained)}.`, focus: "#recon-card", before: () => selectTab("recon") },
    { text: "Daarna één rapport: netto-omzet per maand tegenover target en vorig jaar. Hover over een maand voor de cijfers; elke grafiek heeft ook een tabelweergave.", focus: "#ov-chart-card", before: () => selectTab("overview") },
    { text: "Omzet staat op de verkoper die de klant had op de factuurdatum. Koen B. vertrok eind maart; zijn 2025 blijft van hem en Bram S. start in april op nul. Lijnen zonder verkoper krijgen de eigenaar van dat moment.", focus: "#sales-rep-card", before: () => selectTab("sales") },
    { text: `De pipeline lijkt groter dan ze is: ${int(k.stale_opportunities)} open deals zonder update in meer dan 60 dagen. Dit is het lijstje voor maandag.`, focus: "#pipe-stale-card", before: () => selectTab("pipeline") },
    { text: `13 datakwaliteitsregels, elk met een eigenaar. CRM-gezondheid van ${pct(k.dq_health_before)} naar ${pct(k.dq_health_after)} — wat overblijft vraagt informatie van de klant, niet een script.`, focus: "#crm-rules-card", before: () => selectTab("crm") },
    { text: "Waarom een mens beslist: deze zorggroep heeft één btw-nummer en bijna dezelfde naam voor twee campussen. Het algoritme geeft een hoge score, maar het zijn twee leverplaatsen. Probeer zelf te beslissen.", focus: "#crm-queue-card", before: () => { selectTab("crm"); multiSite(); } },
    { text: "Het datawarehouse zelf, in je browser: dezelfde SQL-views die Power BI gebruikt. Dezelfde views in T-SQL worden in CI op SQL Server 2022 gedraaid en vergeleken.", focus: "#sql-card", before: () => selectTab("sql") },
    { text: "Eerlijk: fictief bedrijf en gegenereerde data; de reviewbeslissingen zijn gesimuleerd; het Power BI-model is als code gevalideerd, maar de DAX is niet in Power BI uitgevoerd. Alles is na te lezen op GitHub.", focus: "#tab-support", before: () => selectTab("overview") },
  ], { label: "Rondleiding", labels: { step: "Stap", of: "van", back: "Terug", next: "Volgende", finish: "Klaar", close: "Sluiten" } });
  $("#btn-tour").addEventListener("click", (e) => { e.preventDefault(); tour.start(); });
}

main().catch((e) => {
  console.error(e);
  document.querySelector(".app-head").append(el("p", { class: "note" }, `De demo kon niet laden: ${e.message}`));
});
